<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>WastedToken Mint — Collectible Physical Challenge Coins</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Courier New', monospace;
            background: linear-gradient(135deg, #0a0a0a 0%, #1a1a2e 100%);
            color: #e0e0e0;
            line-height: 1.6;
            overflow-x: hidden;
        }

        header {
            padding: 2rem;
            text-align: center;
            border-bottom: 2px solid #d4af37;
        }

        h1 {
            font-size: 2.5rem;
            color: #d4af37;
            letter-spacing: 0.1em;
            text-transform: uppercase;
            margin-bottom: 0.5rem;
        }

        .tagline {
            font-size: 0.95rem;
            color: #aaa;
            letter-spacing: 0.05em;
        }

        .hero-section {
            width: 100%;
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 3rem 2rem;
            background: radial-gradient(circle at center, #16213e 0%, #0f3460 100%);
            min-height: 500px;
        }

        #coin-hero {
            width: 400px;
            height: 400px;
            max-width: 100%;
            display: block;
            background: radial-gradient(circle at 40% 40%, #1a1a2e, #0a0a0a);
            border-radius: 50%;
            box-shadow: 0 0 60px rgba(212, 175, 55, 0.3), inset 0 0 40px rgba(0, 0, 0, 0.8);
        }

        .about {
            max-width: 900px;
            margin: 4rem auto;
            padding: 2rem;
            background: rgba(30, 30, 50, 0.5);
            border-left: 4px solid #d4af37;
            border-radius: 4px;
        }

        .about h2 {
            color: #d4af37;
            font-size: 1.8rem;
            margin-bottom: 1rem;
            letter-spacing: 0.05em;
