            margin-bottom: 1rem;
            color: #ccc;
        }

        .collection {
            max-width: 1200px;
            margin: 4rem auto;
            padding: 2rem;
        }

        .collection h2 {
            color: #d4af37;
            font-size: 1.8rem;
            margin-bottom: 2rem;
            text-align: center;
            letter-spacing: 0.05em;
        }

        .edition-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
