            position: relative;
        }

        .edition:hover {
            border-color: #d4af37;
            background: rgba(30, 30, 50, 0.9);
            transform: translateY(-4px);
            box-shadow: 0 8px 20px rgba(212, 175, 55, 0.2);
        }

        .edition-canvas {
            width: 100%;
            height: 180px;
            display: block;
