            border-radius: 4px;
        }

        .edition h3 {
            color: #d4af37;
            font-size: 1.3rem;
            margin-bottom: 0.5rem;
            letter-spacing: 0.05em;
        }

        .edition-status {
            font-size: 0.85rem;
            color: #999;
            margin-bottom: 1rem;
