        .buy:disabled {
            opacity: 0.3;
            cursor: not-allowed;
        }

        footer {
            text-align: center;
            padding: 2rem;
            border-top: 2px solid #d4af37;
            margin-top: 4rem;
            color: #999;
            font-size: 0.9rem;
        }

        @media (max-width: 768px) {
            h1 {
                font-size: 1.8rem;
            }

            #coin-hero {
                width: 280px;
                height: 280px;
            }

            .collection h2, .about h2 {
                font-size: 1.4rem;
            }
