    </style>
</head>
<body>
    <header>
        <h1>⬡ WastedToken Mint ⬡</h1>
        <p class="tagline">Forged Legends, Minted in Metal</p>
    </header>

    <section class="hero-section">
        <canvas id="coin-hero"></canvas>
    </section>

    <section class="about">
        <h2>About WastedToken Mint</h2>
        <p>
            Since 2019, WastedToken Mint has been crafting premium collectible challenge coins 
            for communities, projects, and legends who demand physical proof of their digital legacy.
        </p>
        <p>
            Each coin is precision-minted with hand-detailed dies, polished to a mirror finish, 
            and treated with our proprietary anti-tarnish metallurgy. We believe in making the 
            digital tangible — tokens you can hold, flip, and pass down.
        </p>
        <p>
            From bronze to black obsidian, every edition tells a story. Welcome to the vault.
        </p>
    </section>

    <section class="collection">
        <h2>Current Editions</h2>
        <div class="edition-grid">
            <div class="edition" data-edition="bronze" data-state="available">
                <canvas class="edition-canvas"></canvas>
                <h3>Bronze</h3>
                <div class="edition-status">Classic & Timeless</div>
                <button class="buy">Add to Cart</button>
            </div>

            <div class="edition" data-edition="silver" data-state="available">
                <canvas class="edition-canvas"></canvas>
                <h3>Silver</h3>
                <div class="edition-status">Lustrous Standard</div>
                <button class="buy">Add to Cart</button>
            </div>

            <div class="edition" data-edition="gold" data-state="sold-out">
                <canvas class="edition-canvas"></canvas>
                <h3>Gold</h3>
                <div class="edition-status sold-out">SOLD OUT</div>
                <button class="buy" disabled>Sold Out</button>
            </div>

            <div class="edition" data-edition="black" data-state="coming-soon">
                <canvas class="edition-canvas"></canvas>
                <h3>Black Obsidian</h3>
                <div class="edition-status coming-soon">Minting Winter 2025</div>
                <button class="buy" disabled>Coming Soon</button>
            </div>
        </div>
    </section>

    <footer>
        <p>&copy; 2025 WastedToken Mint. Every token, forever minted.</p>
    </footer>

    <script>
        // Coin parameters
        const COIN_RADIUS = 0.8;
        const COIN_DEPTH = 0.15;
        const REEDED_SEGMENTS = 24;

        // Color schemes for editions
        const METALS = {
            bronze: { base: [0.8, 0.5, 0.2], light: [1.0, 0.7, 0.3], dark: [0.5, 0.25, 0.05] },
            silver: { base: [0.9, 0.9, 0.95], light: [1.0, 1.0, 1.0], dark: [0.7, 0.7, 0.75] },
            gold: { base: [1.0, 0.85, 0.0], light: [1.0, 1.0, 0.4], dark: [0.8, 0.65, 0.0] },
            black: { base: [0.15, 0.15, 0.15], light: [0.4, 0.4, 0.4], dark: [0.05, 0.05, 0.05] }
        };

        // Render coin to canvas
        function renderCoin(canvas, t, edition = 'bronze') {
            const ctx = canvas.getContext('2d');
            const w = canvas.width;
            const h = canvas.height;

            // Clear
            ctx.fillStyle = '#0a0a0a';
            ctx.fillRect(0, 0, w, h);

            // Subtle radial background
            const bgGrad = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
            bgGrad.addColorStop(0, '#1a1a2e');
            bgGrad.addColorStop(1, '#0a0a0a');
            ctx.fillStyle = bgGrad;
            ctx.fillRect(0, 0, w, h);

            const cx = w / 2;
            const cy = h / 2;
            const scale = Math.min(w, h) / 2.4;

            ctx.save();
            ctx.translate(cx, cy);

            // Animate rotation: spin about Y (horizontal flip) and X (vertical rotation)
            const spinY = t * Math.PI * 2; // Full rotation about vertical axis
            const spinX = Math.sin(t * Math.PI) * 0.6; // Flip about horizontal axis

            // 3D projection
            const cosY = Math.cos(spinY);
            const sinY = Math.sin(spinY);
            const cosX = Math.cos(spinX);
            const sinX = Math.sin(spinX);

            // Draw coin as ellipse with 3D effect
            const scaleX = Math.abs(cosY); // Foreshorten width during rotation
            const scaleDepth = Math.abs(sinX); // Show flip depth

            // Render faces based on flip angle
            const faceBlend = Math.abs(sinX); // 0 = front, 1 = back

            // Draw main coin disc
            ctx.save();

            // Perspective scaling
            const perspectiveScale = 0.7 + 0.3 * Math.abs(cosY);
            ctx.scale(perspectiveScale * scaleX, perspectiveScale);

            // Main coin circle with 3D shading
            const metalColor = METALS[edition];
            const ambientLight = 0.4;
            const directionalLight = Math.max(0, cosY);
            const brightness = ambientLight + directionalLight * 0.6;

            // Base coin color
            ctx.fillStyle = `rgb(${Math.round(metalColor.base[0] * brightness * 255)}, ${Math.round(metalColor.base[1] * brightness * 255)}, ${Math.round(metalColor.base[2] * brightness * 255)})`;
            ctx.beginPath();
            ctx.arc(0, 0, scale, 0, Math.PI * 2);
            ctx.fill();

            // Reeded edge effect (only visible from side)
            if (Math.abs(cosY) > 0.1) {
                ctx.strokeStyle = `rgba(${Math.round(metalColor.dark[0] * 255)}, ${Math.round(metalColor.dark[1] * 255)}, ${Math.round(metalColor.dark[2] * 255)}, ${Math.abs(cosY) * 0.8})`;
                ctx.lineWidth = scale * 0.03;
                for (let i = 0; i < REEDED_SEGMENTS; i++) {
                    const angle = (i / REEDED_SEGMENTS) * Math.PI * 2;
                    const x1 = Math.cos(angle) * scale * 0.95;
                    const y1 = Math.sin(angle) * scale * 0.95;
                    const x2 = Math.cos(angle) * scale * 1.0;
                    const y2 = Math.sin(angle) * scale * 1.0;
                    ctx.beginPath();
                    ctx.moveTo(x1, y1);
                    ctx.lineTo(x2, y2);
                    ctx.stroke();
                }
            }

            ctx.restore();

            // Draw face details (embossed text)
            ctx.save();
            ctx.scale(perspectiveScale * scaleX, perspectiveScale);

            ctx.font = `bold ${scale * 0.25}px 'Courier New', monospace`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            // Determine which face to show stronger
            if (faceBlend < 0.5) {
                // Front face (WastedToken emblem)
                ctx.fillStyle = `rgba(212, 175, 55, ${0.9 - faceBlend * 0.5})`;
                ctx.fillText('⬡WT⬡', 0, -scale * 0.15);
                ctx.font = `${scale * 0.12}px 'Courier New', monospace`;
                ctx.fillText('WASTED', 0, scale * 0.15);
                ctx.fillText('TOKEN', 0, scale * 0.28);
            } else {
                // Back face (Token denomination)
                ctx.fillStyle = `rgba(212, 175, 55, ${(faceBlend - 0.5) * 2 * 0.9})`;
                ctx.font = `bold ${scale * 0.18}px 'Courier New', monospace`;
                ctx.fillText('10,000', 0, -scale * 0.1);
                ctx.font = `${scale * 0.14}px 'Courier New', monospace`;
                ctx.fillText('TOKENS', 0, scale * 0.15);
            }

            ctx.restore();

            // Specular highlight (moving with rotation)
            ctx.save();
            const highlightX = Math.cos(spinY) * scale * 0.3;
            const highlightY = Math.sin(spinX) * scale * 0.2;
            const highlightGrad = ctx.createRadialGradient(highlightX, highlightY, 0, highlightX, highlightY, scale * 0.35);
            highlightGrad.addColorStop(0, `rgba(255, 255, 255, ${Math.max(0, cosY) * 0.6})`);
            highlightGrad.addColorStop(0.7, `rgba(255, 255, 255, 0)`);
            highlightGrad.addColorStop(1, `rgba(255, 255, 255, 0)`);
            ctx.fillStyle = highlightGrad;
            ctx.beginPath();
            ctx.arc(highlightX, highlightY, scale * 0.4, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();

            ctx.restore();
        }

        // Initialize hero canvas
        const heroCanvas = document.getElementById('coin-hero');
        heroCanvas.width = 400;
        heroCanvas.height = 400;

        let animationTime = 0;
        let animationId = null;
        let isPaused = false;

        function animate() {
            if (!isPaused) {
                animationTime = (animationTime + 0.01) % 1;
            }
            renderCoin(heroCanvas, animationTime, 'silver');
            animationId = requestAnimationFrame(animate);
        }

        animate();

        // Render edition canvases
        const editionCanvases = document.querySelectorAll('.edition-canvas');
        editionCanvases.forEach(canvas => {
            canvas.width = 300;
            canvas.height = 180;
            const edition = canvas.closest('.edition').dataset.edition;
            renderCoin(canvas, Math.random() * 0.25 + 0.1, edition);
        });

        // API for grading
        window.demo = {
            canvas: heroCanvas,
            setTime(t) {
                renderCoin(heroCanvas, t % 1, 'silver');
            },
            pause() {
                isPaused = true;
            }
        };

        // Button handlers
        document.querySelectorAll('.buy:not(:disabled)').forEach(button => {
            button.addEventListener('click', () => {
                const edition = button.closest('.edition').dataset.edition;
                alert(`Added ${edition.toUpperCase()} coin to cart!`);
            });
        });
    </script>
</body>
</html>
